const lesson6BTNC=[{"file":"Q2B6.NC1.MP3","title":"Nâng cao 1","key":["A","E","D","B","C"],"transcript":["上周末我和家人去参观了一个古老的地方。","周六晚上我去听了一场音乐会，很棒。","上周日我们社区组织了一次植树活动，我参加了。","我上周终于通过了考试，现在可以开车出门了。","我昨晚把报告发给了老师。"],"questions":[["他上周末跟谁一起去参观？",["同事","家人","老师"],1],["他什么时候去听音乐会？",["周六晚上","周日早上","周五下午"],0],["他参加了什么活动？",["篮球比赛","唱歌比赛","植树活动"],2],["他现在可以做什么？",["参加考试","开车出门","去上课"],1],["他把报告发给了谁？",["朋友","经理","老师"],2]]},{"file":"Q2B6.NC2.MP3","title":"Nâng cao 2","key":["B","C","A","E","D"],"transcript":["女：你上周六下午做什么了？打电话你没接。\n男：哦，我在车库帮我爸爸修车呢，手很脏。","男：你昨天发的照片里那家餐厅怎么样？\n女：非常好！我尝试了他们的菜，味道很特别。","女：听说你前天去市中心迷路了？\n男：是啊，我找了好久才找到路。","男：你昨天一整天都没出门吗？\n女：对啊，下雨了，我就在家玩了一整天游戏。","女：你看今天早上的新闻了吗？\n男：还没，我早上一直在忙。是什么新闻？"],"questions":[["他上周六下午帮谁修车？",["朋友","爸爸","老师"],1],["她觉得餐厅怎么样？",["非常好","不好吃","太贵了"],0],["他前天在市中心怎么了？",["看电影了","买东西了","迷路了"],2],["她下雨天在家做什么？",["睡觉","玩游戏","写报告"],1],["他看今天早上的新闻了吗？",["看了","看了一点儿","还没看"],2]]},{"file":"Q2B6.NC3.MP3","title":"Nâng cao 3","key":["A","C","B","B","C"],"transcript":["男：你上个月不是说想学游泳吗？开始学了吗？\n女：学了。我已经上了第一节课，虽然有点怕水，但老师很好。","男：你昨天提交的意见，经理反馈了吗？\n女：他说整体不错，但有几个细节需要修改。我下午改好了。","男：上周的活动你怎么没来？\n女：真可惜，我那天突然发烧了，只好请假在家休息。","男：我昨天在超市看到一个人很像你弟弟。\n女：不可能，我弟弟昨天一整天都在学校复习考试呢。","男：你这双新球鞋真酷！什么时候买的？\n女：谢谢！不是我买的，是我表哥送我的礼物。"],"questions":[["她开始学游泳了吗？",["还没有","已经上了第一节课","不想学"],1],["经理认为哪些地方要修改？",["所有内容","题目","几个细节"],2],["她为什么没参加活动？",["发烧了","要上班","去旅行了"],0],["她弟弟昨天在哪里？",["超市","学校","家里"],1],["新球鞋是谁送的？",["弟弟","老师","表哥"],2]]}];
